INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('dateflow_connect', 'Shuffle the deck and deal 5 cards to each player. On your turn, draw a card and do the This prompt or flip it for the That activity. Each task you complete earns points. Reach certain points to win cool rewards. The game has three levels of cards: Ice Breakers, Bond Builders and Connect Us Deeply.', '["Switch Turns: The next player skips their turn.", "Double Points: Earn double points for the next card completed.", "Wild Card: Choose any card from the deck and complete it.", "Reverse: Change the direction of play.", "Draw Two: The next player draws two cards and completes both prompts."]', NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('dateflow_connect', 'ice', 'Ice Breakers', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('dateflow_connect', 'ice', 0, NULL, 'This', 'Share a quirky or fun fact about yourself.', NULL, 'That', 'Play "Two Truths & A Lie"'),
  ('dateflow_connect', 'ice', 1, NULL, 'This', 'Ask a fun "Would you rather" question.', NULL, 'That', 'Engage in a quick round of charades, each acting out three words or phrases.'),
  ('dateflow_connect', 'ice', 2, NULL, 'This', 'Share your first impression of the other person in a playful way.', NULL, 'That', 'Create a silly handshake together.'),
  ('dateflow_connect', 'ice', 3, NULL, 'This', 'Have a mini dance-off for 30 seconds.', NULL, 'That', 'Mirror each other’s dance moves for 30 seconds.'),
  ('dateflow_connect', 'ice', 4, NULL, 'This', 'Draw a quick doodle of each other.', NULL, 'That', 'Play a quick round of Pictionary using a random word generator on your phone.'),
  ('dateflow_connect', 'ice', 5, NULL, 'This', 'Share a fun memory from your childhood.', NULL, 'That', 'Recreate a scene from that memory using props around you.'),
  ('dateflow_connect', 'ice', 6, NULL, 'This', 'Reveal a funny nickname you had growing up.', NULL, 'That', 'Give each other funny nicknames for the rest of the game.'),
  ('dateflow_connect', 'ice', 7, NULL, 'This', 'Describe your favorite game as a child and why you loved it.', NULL, 'That', 'Teach each other a quick version of a game you played as a kid.'),
  ('dateflow_connect', 'ice', 8, NULL, 'This', 'Who was your first celebrity crush?', NULL, 'That', 'Pretend to be your celebrity crush for a minute.'),
  ('dateflow_connect', 'ice', 9, NULL, 'This', 'Give a genuine compliment to the other person.', NULL, 'That', 'Play the "Compliment Battle" game where you exchange compliments until someone runs out.'),
  ('dateflow_connect', 'ice', 10, NULL, 'This', 'Share your favorite song and why it’s meaningful to you.', NULL, 'That', 'Sing a line from your favorite song together.'),
  ('dateflow_connect', 'ice', 11, NULL, 'This', 'Share a funny joke', NULL, 'That', 'Have a quick laugh battle – first to laugh loses.'),
  ('dateflow_connect', 'ice', 12, NULL, 'This', 'Show or describe a hidden talent.', NULL, 'That', 'Teach each other a simple trick or skill.'),
  ('dateflow_connect', 'ice', 13, NULL, 'This', 'Do you prefer cats, dogs, or another pet? Why?', NULL, 'That', 'Pretend to be your favorite pet for a minute.'),
  ('dateflow_connect', 'ice', 14, NULL, 'This', 'What’s your favorite food and why?', NULL, 'That', 'Describe your favorite food in a funny way without naming it and let the other guess.'),
  ('dateflow_connect', 'ice', 15, NULL, 'This', 'Share a funny story that happened to you recently.', NULL, 'That', 'Reenact the funny story together.');
