  ('dateflow_connect', 'deep', 5, NULL, 'This', 'Talk about a deep fear you have and how you deal with it.', NULL, 'That', 'Write down ways you can help each other face these fears.'),
  ('dateflow_connect', 'deep', 6, NULL, 'This', 'Discuss your core values and why they matter to you.', NULL, 'That', 'Create a mini manifesto of your shared values.'),
  ('dateflow_connect', 'deep', 7, NULL, 'This', 'Share your philosophy on life.', NULL, 'That', 'Write a short poem or motto that encapsulates your life philosophies.'),
  ('dateflow_connect', 'deep', 8, NULL, 'This', 'What does love mean to you?', NULL, 'That', 'Write a love letter to each other.'),
  ('dateflow_connect', 'deep', 9, NULL, 'This', 'Describe your vision for the future.', NULL, 'That', 'Draw a timeline of your envisioned future together.'),
  ('dateflow_connect', 'deep', 10, NULL, 'This', 'How do you support your emotional well-being?', NULL, 'That', 'Share and practice a favorite emotional support technique together.'),
  ('dateflow_connect', 'deep', 11, NULL, 'This', 'Discuss the importance of personal boundaries.', NULL, 'That', 'Role-play a scenario where you each assert your boundaries.'),
  ('dateflow_connect', 'deep', 12, NULL, 'This', 'What’s an important life lesson you’ve learned?', NULL, 'That', 'Write down and exchange the most important lessons you’ve learned.'),
  ('dateflow_connect', 'deep', 13, NULL, 'This', 'Share a favorite memory of your time together.', NULL, 'That', 'Create a scrapbook page or a digital memory of that moment.'),
  ('dateflow_connect', 'deep', 14, NULL, 'This', 'Talk about your ultimate purpose in life.', NULL, 'That', 'Write a mission statement for your lives and exchange them.'),
  ('dateflow_connect', 'deep', 15, NULL, 'This', 'What kind of legacy do you want to leave behind?', NULL, 'That', 'Design a small tribute or symbol representing your legacy.');
INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('date_guru', 'Draw a card and read the lesson. Flip it for the idea behind it, then try it on your next date.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('date_guru', 'main', '52 lessons', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('date_guru', 'main', 0, 'The Power of Eye Contact', NULL, 'Gaze, don’t stare.', NULL, 'The idea', 'Hold strong eye contact that feels natural. Let your eyes speak your confidence, but never make it uncomfortable. Look into the left eye in the beginning & often. Imagine a thread connecting your gaze to theirs, communicating trust and presence.'),
  ('date_guru', 'main', 1, 'Smile Like You Mean It', NULL, 'Smile with your heart.', NULL, 'The idea', 'Remember that your smile activates mirror neurons in others. Use your smile to connect on a deeper, subconscious level and instantly make the interaction warmer and more inviting.'),
  ('date_guru', 'main', 2, 'Confidence Through Proximity', NULL, 'Close the distance,', NULL, 'The idea', 'but don’t invade.” Being physically closer to someone creates a natural connection, but respect their personal space. Adjust proximity based on how comfortable they seem.'),
  ('date_guru', 'main', 3, 'Tonality is Everything', NULL, 'Rapport breaking, never rapport seeking.', NULL, 'The idea', 'Speak with a low pitch and calm tonality. Avoid sounding needy. A powerful voice sets the tone for confidence. Practice delivering your words with intentional weight behind them.'),
  ('date_guru', 'main', 4, 'Relax, You''re in Control', NULL, 'Breathe in, let go, and smile internally.', NULL, 'The idea', 'When feeling nervous, take a deep breath, and focus on releasing tension. Center yourself before approaching. Your inner calm will be projected externally.'),
  ('date_guru', 'main', 5, 'Create Safety and Trust', NULL, 'The best connection', NULL, 'The idea', 'starts with trust.” Show genuine interest in the person, and make them feel safe around you. Never rush into topics that feel too personal too soon. Build trust organically.'),
  ('date_guru', 'main', 6, 'Be Playful, Be Curious', NULL, 'Light-hearted curiosity', NULL, 'The idea', 'is magnetic.” Ask playful questions, engage in light teasing, and use humor to break the ice. Curiosity creates intrigue and an easy-going vibe that others are drawn to.'),
  ('date_guru', 'main', 7, 'Detach from Outcomes', NULL, 'Engage, but don’t', NULL, 'The idea', 'cling to the result.” Enjoy the interaction for what it is without expectations. When you detach from needing a certain outcome, your energy is lighter, and people will sense that freedom.'),
  ('date_guru', 'main', 8, 'Lead with High Energy', NULL, 'Your energy sets the pace of the interaction.', NULL, 'The idea', 'Enter every conversation with an upbeat vibe. Your energy is contagious. Keep it positive, and don’t let low moments bring you down.'),
  ('date_guru', 'main', 9, 'Acknowledge Their World', NULL, 'Step into their world before', NULL, 'The idea', 'you invite them into yours.” Pay attention to their mood, their interests, and what they are expressing. Show that you care about what matters to them before sharing about yourself.'),
  ('date_guru', 'main', 10, 'Storytelling Power', NULL, 'Stories connect us to the heart.', NULL, 'The idea', 'Learn to share personal stories in a fun, engaging way. Keep them concise, and let them reflect your personality. Great stories deepen connection.'),
  ('date_guru', 'main', 11, 'Play the Curiosity Game', NULL, 'Ask intriguing questions', NULL, 'The idea', 'that unlock new layers.” Instead of sticking to the basics, ask something that makes the conversation different. Example: “What’s the one thing you’d do if you had no fear?”'),
  ('date_guru', 'main', 12, 'Anchoring with Touch', NULL, 'Touch subtly, touch naturally.', NULL, 'The idea', 'When it feels appropriate, use light, casual touches to create connection. Whether it’s a tap on the shoulder or a handshake, touch deepens rapport.'),
  ('date_guru', 'main', 13, 'The Energy Mirror', NULL, 'Reflect the energy they bring.', NULL, 'The idea', 'Match their energy at the start of the conversation and gradually lead them toward a more engaged, upbeat vibe. This creates comfort and rapport.'),
  ('date_guru', 'main', 14, 'Mystery Creates Magnetism', NULL, 'Don’t reveal everything at once.', NULL, 'The idea', 'Leave parts of yourself hidden to create intrigue. Slowly unfold more about yourself as the interaction progresses, keeping them curious.'),
  ('date_guru', 'main', 15, 'Engage Through Silence', NULL, 'Sometimes the pause speaks louder than words.', NULL, 'The idea', 'Don’t be afraid to pause in conversation. Silence allows moments to breathe and creates space for deeper reflection. Use it wisely.'),
  ('date_guru', 'main', 16, 'Stay in the Present', NULL, 'Your focus on the moment', NULL, 'The idea', 'builds deeper connection.” Forget the past or future worries, and immerse yourself fully in the conversation. Being present gives the other person your undivided attention.'),
  ('date_guru', 'main', 17, 'Practice Confidence Daily', NULL, 'Confidence is a muscle.', NULL, 'The idea', 'Strengthen it daily.” Every day, practice affirming your value and capabilities. Confidence grows with consistent practice in all areas of life, not just dating.'),
  ('date_guru', 'main', 18, 'Mirror Empowerment', NULL, 'Speak to yourself as', NULL, 'The idea', 'your best coach.” Stand in front of a mirror, make eye contact with yourself, and affirm: “I am capable, worthy, and magnetic.” Do this each day to condition your mind for confidence.'),
  ('date_guru', 'main', 19, 'Avoid Over-Qualification', NULL, 'Never try to prove yourself.', NULL, 'The idea', 'You’re already enough.” Don’t slip into explaining or justifying your value. Let your actions and energy speak. Remember, you have nothing to prove to anyone.'),
  ('date_guru', 'main', 20, 'The Smile Trigger', NULL, 'Smile within; the outside will follow.', NULL, 'The idea', 'Before any approach, mentally activate a smile from within. This helps set a positive tone for the interaction and lowers social barriers.'),
  ('date_guru', 'main', 21, 'Find the Right Wingman Energy', NULL, 'Your wingman should', NULL, 'The idea', 'amplify, not drain.” When choosing a wingman, pick someone who matches your energy and uplifts the dynamic. Avoid those who rely too heavily on you for motivation.'),
  ('date_guru', 'main', 22, 'Shift Energy with Movement', NULL, 'When stuck, move.', NULL, 'The idea', 'If energy feels stagnant, shift it by changing your physical state. Move, stretch, or walk around to create new momentum before engaging with others.'),
  ('date_guru', 'main', 23, 'Power Poses Before Approach', NULL, 'Stand tall, shoulders', NULL, 'The idea', 'back, chin up.” Before any interaction, assume a power pose for two minutes. It increases testosterone and confidence while lowering cortisol.'),
  ('date_guru', 'main', 24, 'Embrace Rejection', NULL, 'Rejection is feedback,', NULL, 'The idea', 'not failure.” Every no gets you closer to a yes. Reframe rejection as valuable feedback, and keep moving forward without attachment to any single outcome.');
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('date_guru', 'main', 25, 'Energy Visualization', NULL, 'Visualize success,', NULL, 'The idea', 'feel success.” Before approaching, visualize yourself interacting effortlessly, making people smile, and leaving a positive impression. This primes your subconscious mind for success.'),
  ('date_guru', 'main', 26, 'The Trust Formula', NULL, 'Trust is earned through authenticity.', NULL, 'The idea', 'Be real, vulnerable, and honest. Trust takes time, but authenticity accelerates the process. Let your genuine self show, even if it feels risky.'),
  ('date_guru', 'main', 27, 'Be Unapologetically You', NULL, 'The right people will be', NULL, 'The idea', 'drawn to your truth.” Never water down your personality to fit someone else’s expectations. The more you embrace who you are, the more aligned connections you’ll attract.'),
  ('date_guru', 'main', 28, 'Hold Space with Silence', NULL, 'Confidence is often', NULL, 'The idea', 'found in silence.” Don’t rush to fill every pause with words. Allow moments of silence to linger. They communicate calmness and show you’re comfortable in your own skin.'),
  ('date_guru', 'main', 29, 'The Compliment Balance', NULL, 'Compliments should', NULL, 'The idea', 'be rare but real.” When you compliment someone, make it sincere and specific. Avoid overloading them with praise—it can come off as seeking approval. A well-timed, genuine compliment carries more weight.'),
  ('date_guru', 'main', 30, 'Use Playful Teasing', NULL, 'A light tease builds connection.', NULL, 'The idea', 'Teasing in a playful, kind-hearted way shows confidence and creates a fun dynamic. Keep it gentle and avoid any negativity or hurtful remarks.'),
  ('date_guru', 'main', 31, 'The Art of the Reframe', NULL, 'Reframe negatives', NULL, 'The idea', 'into positives.” When faced with a challenging situation or negative energy, reframe it into something positive. Ex: If someone mentions a flaw, playfully turn it into an interesting quirk or strength.'),
  ('date_guru', 'main', 32, 'Focus on the Feeling', NULL, 'The emotional connection matters more than the words.', NULL, 'The idea', 'Rather than focusing solely on what’s being said, tune into how the conversation feels. Emotion is the foundation of deeper connection.'),
  ('date_guru', 'main', 33, 'Expand Your Energy', NULL, 'Hold a bigger space energetically.', NULL, 'The idea', 'Before entering a room, take a deep breath and visualize your energy expanding outward. Picture yourself confidently filling the space, naturally attracting attention.'),
  ('date_guru', 'main', 34, 'Calibration is Key', NULL, 'Always adjust to the', NULL, 'The idea', 'vibe of the moment.” Pay attention to the energy of the interaction, and adjust your approach accordingly. Calibration shows emotional intelligence and deepens rapport.'),
  ('date_guru', 'main', 35, 'Lead and Guide the Interaction', NULL, 'Take the lead, but be gentle.', NULL, 'The idea', 'Set the tone of the conversation, but don’t dominate it. Gently guide the flow while being receptive to their input. Leading shows strength, but adaptability shows care.'),
  ('date_guru', 'main', 36, 'Give, Don’t Take', NULL, 'Focus on adding value,', NULL, 'The idea', 'not taking it.” In every interaction, think about what you can offer—whether it’s positivity, humor, or a kind word. Giving creates a natural exchange of energy that feels good for both parties.'),
  ('date_guru', 'main', 37, 'Don’t Be Afraid to Walk Away', NULL, 'Walking away can be', NULL, 'The idea', 'a powerful move.” Sometimes, disengaging shows more confidence than sticking around. Know when to gracefully exit an interaction that’s not serving you or doesn’t feel aligned.'),
  ('date_guru', 'main', 38, 'Remember Their Name', NULL, 'Use their name to', NULL, 'The idea', 'create familiarity.” Names hold power. When you say someone’s name in conversation, it creates a sense of closeness. Make it a point to remember and use their name naturally.'),
  ('date_guru', 'main', 39, 'Detach from Reactions', NULL, 'Their reaction is not a reflection of your worth.', NULL, 'The idea', 'Don’t internalize how someone reacts to you. Whether they respond positively or negatively, remain centered in your own value. Their reaction is a reflection of them, not you.'),
  ('date_guru', 'main', 40, 'Be Open to Playfulness', NULL, 'Let your inner child guide you.', NULL, 'The idea', 'Don’t be afraid to get playful and light-hearted. This breaks down barriers and creates a sense of ease. Engage with the moment like a curious child, without overthinking.'),
  ('date_guru', 'main', 41, 'The Mirror Technique', NULL, 'Mirror their body language', NULL, 'The idea', 'subtly to build rapport.” If someone leans forward, you can subtly lean forward. If they use hand gestures, mirror those gestures. It’s a psychological technique that helps build a subconscious connection.'),
  ('date_guru', 'main', 42, 'Stay Curious About Their Story', NULL, 'Everyone has a story; be genuinely interested.', NULL, 'The idea', 'Ask questions that invite people to share their experiences and passions. Curiosity shows that you care about who they are, not just what they can offer you.'),
  ('date_guru', 'main', 43, 'Share Wins and Losses', NULL, 'Being real creates', NULL, 'The idea', 'real connections.” Don’t only share your successes. Open up about your challenges or mistakes. This humanizes you and fosters a deeper, more authentic bond.'),
  ('date_guru', 'main', 44, 'The Power of Vulnerability', NULL, 'Being open shows strength,', NULL, 'The idea', 'not weakness.” Don’t be afraid to show your vulnerability when appropriate. It allows the other person to see the real you and often encourages them to open up as well.'),
  ('date_guru', 'main', 45, 'Embrace the Unexpected', NULL, 'Surprises create excitement and novelty.', NULL, 'The idea', 'If something unexpected happens during the interaction, embrace it. Unpredictable moments often become the most memorable and fun experiences.'),
  ('date_guru', 'main', 46, 'Keep It Light at First', NULL, 'Start playful, then', NULL, 'The idea', 'gradually deepen.” The best connections often begin with light, playful banter. As rapport builds, naturally let the conversation deepen into more personal and meaningful topics.'),
  ('date_guru', 'main', 47, 'Be Present, Stay Engaged', NULL, 'Distractions dilute', NULL, 'The idea', 'connection.” When engaging with someone, put your phone away and be fully present. It shows respect, and they will appreciate your undivided attention.'),
  ('date_guru', 'main', 48, 'Laugh Often', NULL, 'Laughter dissolves tension &', NULL, 'The idea', 'builds instant connection.” Don’t take things too seriously. Inject humor and laughter into conversations, as it helps create a relaxed and enjoyable atmosphere for both of you.'),
  ('date_guru', 'main', 49, 'Build Momentum Gradually', NULL, 'Every interaction is a step', NULL, 'The idea', 'toward deeper rapport.” View every conversation as a building block. Don’t rush the connection. Build momentum gradually, letting trust and attraction grow naturally over time.');
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('date_guru', 'main', 50, 'Test Comfort Levels', NULL, 'Check in with their comfort', NULL, 'The idea', 'through subtle cues.” Gauge someone’s comfort by observing body language, energy shifts, or tone of voice. Adjust accordingly if they seem uncomfortable, and always respect boundaries.'),
  ('date_guru', 'main', 51, 'Embrace Who You Are', NULL, 'You are enough, exactly as you are.', NULL, 'The idea', 'The most attractive thing you can bring to any interaction is your authentic self. Embrace your quirks, your uniqueness, and your flaws. Confidence comes from owning who you are.');
INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('healflow', 'Take turns drawing a card and doing what it says together.', '["Double Points: Double the points for the next 2 prompts.", "Swap: Swap a card with another player.", "Wildcard: Player chooses any card from the deck."]', 'Pick any one.', NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('healflow', 'emotions', 'Emotions', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('healflow', 'emotions', 0, 'Emotion Charades', NULL, 'Act out an emotion without speaking. Let others guess the emotion. Discuss why it might be important to understand this emotion in our family.', NULL, NULL, NULL),
  ('healflow', 'emotions', 1, 'Feelings Journal', NULL, 'Each family member shares one emotion they felt strongly this week/day. also Discuss why you felt that way.', NULL, NULL, NULL),
  ('healflow', 'emotions', 2, 'Emotion Wheel', NULL, 'Discuss a time you felt a specific emotion. How did it impact your week/day?', NULL, NULL, NULL),
  ('healflow', 'emotions', 3, 'Mirror, Mirror', NULL, 'Pair up and mimic each other’s facial expressions. Guess the emotion being portrayed.', NULL, NULL, NULL),
  ('healflow', 'emotions', 4, 'Mood Mapping', NULL, 'Describe your emotional highs and lows of the week.', NULL, NULL, NULL),
  ('healflow', 'emotions', 5, 'Emotion Stories', NULL, 'Share a story from your life where a specific emotion played a major role.', NULL, NULL, NULL),
  ('healflow', 'emotions', 6, 'Feelings Bingo', NULL, 'Discuss different emotions you felt during the week. Reflect on the reasons behind them.', NULL, NULL, NULL),
  ('healflow', 'emotions', 7, 'Emotion Match', NULL, 'Match emotions to scenarios described by family members. Discuss why the emotion fits the scenario well.', NULL, NULL, NULL),
  ('healflow', 'emotions', 8, 'Yes, And... OR Questions Only', NULL, 'One person starts a statement, and the next person must add to it with Yes, and... or optionally use questions only statements to build upon the idea. Last one standing wins.', NULL, NULL, NULL),
  ('healflow', 'emotions', 9, 'Questions Only', NULL, 'Hold a conversation where participants can only ask questions. This helps in understanding how to inquire deeply without making assumptions.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('healflow', 'stories', 'Stories', NULL, 1);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('healflow', 'stories', 0, 'Story-time Relay', NULL, 'Start a story about a happy family memory. Each member adds to the story, making it more detailed.', NULL, NULL, NULL),
  ('healflow', 'stories', 1, 'The Day I Felt Proud', NULL, 'Share a story about a day you felt proud of a family member. Reflect on their qualities that made you feel proud.', NULL, NULL, NULL),
  ('healflow', 'stories', 2, 'Memory Lane', NULL, 'Discuss a fond family memory and its impact on your life.', NULL, NULL, NULL),
  ('healflow', 'stories', 3, 'Future Stories', NULL, 'Imagine a future family event (e.g., a wedding, a trip). Create a story around it.', NULL, NULL, NULL),
  ('healflow', 'stories', 4, 'Family Legends', NULL, 'Share stories about family members who aren’t present. Discuss their impact on the family.', NULL, NULL, NULL),
  ('healflow', 'stories', 5, 'Hero of the Day', NULL, 'Pick a family member to be the hero of the day. Each member shares a story highlighting the hero’s qualities.', NULL, NULL, NULL),
  ('healflow', 'stories', 6, 'Tall Tales', NULL, 'Each member creates a fun, exaggerated story about a common family experience.', NULL, NULL, NULL),
  ('healflow', 'stories', 7, 'Story Cubes', NULL, 'Create a story together based on given prompts.', NULL, NULL, NULL),
  ('healflow', 'stories', 8, 'Time Capsule', NULL, 'Imagine creating a family time capsule. Discuss what each member would include and why.', NULL, NULL, NULL),
  ('healflow', 'stories', 9, 'Milestone Moments', NULL, 'Share stories about significant family milestones & their overall impact.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('healflow', 'activities', 'Activities', NULL, 2);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('healflow', 'activities', 0, 'Forgiveness Circle', NULL, 'Each member shares something they seek forgiveness for. Others respond with understanding and forgiveness.', NULL, NULL, NULL),
  ('healflow', 'activities', 1, 'Gratitude Jar', NULL, 'Share things you are grateful for about each family member.', NULL, NULL, NULL),
  ('healflow', 'activities', 2, 'Support System', NULL, 'Discuss ways you can support each other better. Create a family support plan.', NULL, NULL, NULL),
  ('healflow', 'activities', 3, 'Compassion Exercise', NULL, 'Share a recent challenge. Family members offer compassionate responses and support.', NULL, NULL, NULL),
  ('healflow', 'activities', 4, 'Healing Words', NULL, 'Write a healing message to a family member. Exchange and discuss the messages.', NULL, NULL, NULL),
  ('healflow', 'activities', 5, 'Mindful Breathing', NULL, 'Practice a mindful breathing exercise together. Discuss the experience.', NULL, NULL, NULL),
  ('healflow', 'activities', 6, 'Affirmation Circle', NULL, 'Each member shares affirmations for themselves and others.', NULL, NULL, NULL),
  ('healflow', 'activities', 7, 'Silent Gratitude', NULL, 'Sit in silence, reflecting on things you are grateful for. Share your reflections afterward.', NULL, NULL, NULL),
  ('healflow', 'activities', 8, 'Kindness Challenge', NULL, 'Set a kindness challenge for the week. Share acts of kindness at the next family gathering.', NULL, NULL, NULL),
  ('healflow', 'activities', 9, 'Meditation Moments', NULL, 'Practice a short guided meditation together. Share how it made you feel.', NULL, NULL, NULL),
  ('healflow', 'activities', 10, 'Empathy Walk', NULL, 'Pair up and walk around the room, taking turns to talk about your feelings while the other listens silently and empathetically.', NULL, NULL, NULL),
  ('healflow', 'activities', 11, 'Reflective Listening', NULL, 'Practice reflective listening by repeating back what a family member says to show understanding.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('healflow', 'improv', 'Improv', NULL, 3);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('healflow', 'improv', 0, 'Improv Scene', NULL, 'Create a short improv scene based on a given scenario. For example, "A day at the beach" or "Cooking together."', NULL, NULL, NULL),
  ('healflow', 'improv', 1, 'Role Reversal', NULL, 'Act out a common family scenario, but switch roles. For example, kids play parents and parents play kids.', NULL, NULL, NULL),
  ('healflow', 'improv', 2, 'Yes, And…', NULL, 'Build a story together, with each sentence starting with "Yes, and…" Continue until someone makes a mistake. The person who makes the mistake gets a fun penalty (e.g., sing a funny song).', NULL, NULL, NULL),
  ('healflow', 'improv', 3, 'Mime Time', NULL, 'Act out a scene silently. Others guess what is happening.', NULL, NULL, NULL),
  ('healflow', 'improv', 4, 'improvised Songs', NULL, 'Create a song about a family event or member. Perform it together.', NULL, NULL, NULL),
  ('healflow', 'improv', 5, 'Freeze Frame', NULL, 'Act out a scene and freeze at a random moment. Others guess what happens next.', NULL, NULL, NULL),
  ('healflow', 'improv', 6, 'Emotion Switch', NULL, 'Act out a scene, switching emotions halfway through.', NULL, NULL, NULL),
  ('healflow', 'improv', 7, 'Sound Effects', NULL, 'Create a scene with one person providing sound effects. Others act out the scene.', NULL, NULL, NULL),
  ('healflow', 'improv', 8, 'Improvised News', NULL, 'Create a news report about a fun family event. Perform it together.', NULL, NULL, NULL),
  ('healflow', 'improv', 9, 'Storytelling with Props', NULL, 'Each member picks an imaginary prop and uses it in a story. The others guess what the prop is.', NULL, NULL, NULL),
  ('healflow', 'improv', 10, 'Building Bridges', NULL, 'Use your body to form a bridge. The rest of the family must find a way to pass under or over it with-out touching the bridge.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('healflow', 'inner', 'Inner Child', NULL, 4);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('healflow', 'inner', 0, 'Childhood Game', NULL, 'Each member teaches the family their favorite childhood game. Play together.', NULL, NULL, NULL),
  ('healflow', 'inner', 1, 'Childhood Dreams', NULL, 'Share a dream or aspiration you had as a child. Reflect on how it has influenced you.', NULL, NULL, NULL),
  ('healflow', 'inner', 2, 'Inner-Child Letters', NULL, 'Write a letter to your inner child. Share and discuss the letters.', NULL, NULL, NULL),
  ('healflow', 'inner', 3, 'Toy Stories', NULL, 'Share a story about a favorite childhood toy. Reflect on why it was special.', NULL, NULL, NULL),
  ('healflow', 'inner', 4, 'Play Day', NULL, 'Dedicate an hour to playing like children. Use toys, games, or outdoor activities.', NULL, NULL, NULL),
  ('healflow', 'inner', 5, 'Imaginary Friends', NULL, 'Share if you had an imaginary friend. Discuss the role they played in your childhood.', NULL, NULL, NULL),
  ('healflow', 'inner', 6, 'Dream Drawing', NULL, 'Draw a dream you had as a child. Share and discuss the drawings.', NULL, NULL, NULL),
  ('healflow', 'inner', 7, 'Childhood Playlist', NULL, 'Create a playlist of songs you loved as a child. Listen and dance together.', NULL, NULL, NULL),
  ('healflow', 'inner', 8, 'Childhood Book', NULL, 'Share and read a passage from your favourite childhood book.', NULL, NULL, NULL);
INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('funflow', 'Pick a deck, draw a card and play what it says. Most games work with 2 or more people; 2 to 6 is best.', NULL, NULL, '["Number of players: Most games can be played by 2 or more people. For best results, 2 to 6 players are recommended.", "Turn-based play: Players take turns. On each turn, the player follows the game on the card, such as asking a question, making a guess or doing a task.", "Time limit (optional): In some games, like 20 Questions and Guess the Sound, set a time limit for answers, for example 30 seconds, to keep the game moving.", "No repeats: A card or idea used once in a round cannot be used again by any player for the rest of the round.", "Points and winning (optional): Give points for right guesses, good actions or a round with no mistakes. The first player to a set number of points, for example 10, wins.", "Respect and fun: Always be respectful and keep the mood light. The goal is to have fun, build connections and be creative.", "Tie-breakers: If there is a tie, use a quick round like Rock, Paper, Scissors to find the winner.", "Adaptability: Feel free to change the rules or make your own house rules to suit the mood and the group.", "20 Questions: The player thinking of the person, place or thing may only answer yes or no. The guessing player gets exactly 20 questions.", "Two Truths and a Lie: Each player gives three statements, two true and one false, in one turn. The other player gets one guess at the lie.", "Story Chain: Players build on the previous sentence, and each sentence must be grammatically correct. Nothing said before can be erased."]');
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('funflow', 'endorphins', 'Endorphins', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'endorphins', 0, 'Joke Battle', NULL, 'Take turns telling jokes. The first person to laugh loses the round.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 1, 'Imitation Game', NULL, 'Mimic someone’s behavior or speech, and your partner guesses who it is.', '["Mimic a famous actor like Leonardo DiCaprio", "Mimic a mutual friend who has a distinct gesture", "Imitate a teacher or professor from school", "Mimic a famous YouTube personality", "Act like a well-known politician", "Imitate a boss or manager at work", "Mimic a famous sports figure", "Act like a celebrity with a unique voice, such as Morgan Freeman", "Mimic a cartoon character (e.g., SpongeBob SquarePants)", "Act like a famous superhero (e.g., Iron Man, Batman)", "Mimic a character from a popular TV show (e.g., Joey from Friends)", "Act like a flight attendant giving safety instructions", "Mimic a famous chef from a cooking show (e.g., Gordon Ramsay)", "Imitate a radio show host announcing the news", "Mimic a famous singer during a concert (e.g., Beyoncé on stage)."]', NULL, NULL),
  ('funflow', 'endorphins', 2, '20-Second Drawing', NULL, 'Describe how you would draw something imaginary using only words. Your partner then describes what they imagined', NULL, NULL, NULL),
  ('funflow', 'endorphins', 3, 'Silent Acting', NULL, 'Act out an action silently, and your partner must guess what you’re doing.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 4, 'Speech Switch', NULL, 'Give a short speech on a random topic, switching topics every 30 seconds.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 5, 'Emotional Charades', NULL, 'Act out an emotion, and your partner guesses what it is.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 6, 'The Mimic Game', NULL, 'Make a face or gesture, and your partner must mimic it exactly.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 7, 'One-Minute Monologue', NULL, 'Speak for one minute on a random topic without pausing.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 8, 'Sound Guess', NULL, 'Make a sound with your mouth, and your partner guesses what it represents', NULL, NULL, NULL),
  ('funflow', 'endorphins', 9, 'Speed Compliments', NULL, 'Rapidly exchange compliments with your partner. Hesitate or repeat, and you lose!', NULL, NULL, NULL),
  ('funflow', 'endorphins', 10, 'Charades', NULL, 'Act out a word or phrase without speaking, and your partner guesses what it is.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 11, 'Rock, Paper, Scissors', NULL, 'Simultaneously throw rock, paper, or scissors. Rock beats scissors, scissors beat paper, & paper beats rock.', NULL, NULL, NULL),
  ('funflow', 'endorphins', 12, 'Rhyme Time', NULL, 'Take turns saying words that rhyme until someone can’t come up with a new one.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('funflow', 'oxytocin', 'Oxytocin', NULL, 1);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'oxytocin', 0, 'Story Chain', NULL, 'Start a story with one sentence, and your partner adds the next. Continue building together.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 1, 'Who Am I?', NULL, 'Think of a famous person, and your partner asks yes-or-no questions to guess who.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 2, 'Would You Rather?', NULL, '?9 Would you rather have a million dollars or the ability to speak every language6 89 Would you rather travel to space or explore the deepest parts of the ocean6 9 Would you rather have 10 minutes of fame or a lifetime of anonymity6 9 Would you rather live without the internet or live without air conditioning6 9 Would you rather always be 10 minutes late or 20 minutes early6 9 Would you rather be able to fly or be invisible6 9 Would you rather lose your phone forever or lose your ability to remember names6 9 Would you rather live 100 years in the past or 100 years in the future6 9 Would you rather read minds or be able to teleport6 ?9 Would you rather have more time or more money6 ??9 Would you rather always laugh loudly at the wrong moment or never laugh at all6 ?89 Would you rather go on a bad date with good food or a good date with bad food6 ? 9 Would you rather always have to make the first move or wait forever for someone else to6 ?9 Would you rather accidentally text your crush or accidentally text your boss something embarrassing6 ?9 Would you rather always get a text back late or never get a reply at all? 16', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 3, 'Charades', NULL, 'Act out a word or phrase without speaking, and your partner guesses what it is.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 4, 'Word Association', NULL, 'Say the first word that comes to mind. Your partner responds with the next associated word. Sample Word Sets/ *- "Ocean" (response: "Wave"# B- "Coffee" (response: "Mug"# - "Mountain" (response: "Climb"# %- "Pizza" (response: "Cheese"# - "Tree" (response: "Forest"# =- "Sky" (response: "Cloud"# ;- "Sun" (response: "Hot"# - "Book" (response: "Read"# - "Night" (response: "Moon"# *- "Rain" (response: "Umbrella")', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 5, 'ABC Storytelling', NULL, 'Create a story where each sentence starts with the next letter of the alphabet.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 6, 'Follow the Leader', NULL, 'Mimic each movement the leader makes, adding new movements as you go. Movement Examples! %K Clap twice, then snap fingersK HK Pat head and rub stomachK K Spin around and then touch your toesK K Hop on one foot three timesK K Wave your hands in the air and jumpK 8K Pretend to fly like a birdK <K March in place while hummingK K Spin around while clapping handsK 2K Pretend to throw a basketballK %K Mimic swimming motions.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 7, 'Sound Effects Storytelling', NULL, 'Tell a story while your partner provides sound effects using only their voice. ________________________ Animal Sounds Make an animal sound, and your partner guesses the animal.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 8, 'I am not crying, you are!', NULL, '.- What’s the most beautiful thing you have been told- ,- When was the last time you cried? and Why# - Is there someone you still think about? What reminds you of them# - What’s a feeling that you miss# - Who was your first love & why did you fall in love with them# - What’s your biggest regret?', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 9, 'One-Word Story', NULL, 'Build a story together, each contributing just one word at a time.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 10, 'Echo Game', NULL, 'One player says a word or phrase, and the other repeats it exactly.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 11, 'Mirror Game', NULL, 'One player moves, and the other mirrors their movements exactly.', NULL, NULL, NULL),
  ('funflow', 'oxytocin', 12, 'Emotion Switch', NULL, 'Express an emotion through facial expressions and voice. Your partner guesses and then imitates it.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('funflow', 'serotonin', 'Serotonin', NULL, 2);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'serotonin', 0, 'Two Truths and a Lie', NULL, 'Share two truths and one lie about yourself. The other player guesses which one is the lie.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 1, 'Speed Compliments', NULL, 'Rapidly exchange compliments with your partner. Hesitate or repeat, and you lose!', NULL, NULL, NULL),
  ('funflow', 'serotonin', 2, 'Compliment Chain', NULL, 'Take turns giving compliments, with each one starting with the last letter of the previous compliment.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 3, 'Memory Recall', NULL, 'Describe a shared memory, and your partner recalls as many details as possible.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 4, 'Compliment Relay', NULL, 'Pass along compliments, each starting with the last letter of the previous one.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 5, 'What’s Missing?', NULL, 'Describe a familiar scene, leaving out one item. Your partner must identify what''s missing.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 6, 'Guess the Sound', NULL, 'One player makes a sound, and the other guesses what it is.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 7, 'Describe the Object', NULL, 'Describe an object using only adjectives. Your partner guesses the object.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 8, 'Counting Categories', NULL, 'Count aloud to 20, replacing multiples of 3 with words related to a chosen category.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 9, 'Spot the Difference', NULL, 'One player changes something small about their appearance. The other must spot the difference.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 10, 'What If?', NULL, 'Ask "What if?" questions and answer what you''d do in that scenario.', NULL, NULL, NULL),
  ('funflow', 'serotonin', 11, 'Mind Meld', NULL, 'Both players say a word. Then try to say a word that connects the two previous ones. Sample Rounds. ), Player 1: "Sun" | Player 2: "Beach" → Word: "Vacation" 8, Player 1: "Coffee" | Player 2: "Morning" → Word: "Caffeine" , Player 1: "Rain" | Player 2: "Sky" → Word: "Cloud" , Player 1: "Movie" | Player 2: "Popcorn" → Word: "Cinema" , Player 1: "Car" | Player 2: "Road" → Word: "Trip" <, Player 1: "Dog" | Player 2: "Park" → Word: "Walk" D, Player 1: "Laptop" | Player 2: "Desk" → Word: "Work" , Player 1: "Tree" | Player 2: "Leaf" → Word: "Nature" , Player 1: "Mountain" | Player 2: "Hike" → Word: "Adventure" ), Player 1: "Book" | Player 2: "Library" → Word: "Reading" )), Player 1: "Moon" | Player 2: "Night" → Word: "Dreams" )8, Player 1: "Pizza" | Player 2: "Cheese" → Word: "Delicious" ), Player 1: "Guitar" | Player 2: "Music" → Word: "Concert" ), Player 1: "Plane" | Player 2: "Sky" → Word: "Travel" ), Player 1: "Snow" | Player 2: "Winter" → Word: "Cold" )<, Player 1: "Pen" | Player 2: "Paper" → Word: "Writing" )D, Player 1: "Dance" | Player 2: "Music" → Word: "Rhythm" ), Player 1: "Camera" | Player 2: "Smile" → Word: "Photo" ), Player 1: "Coffee" | Player 2: "Cup" → Word: "Break" 8, Player 1: "Window" | Player 2: "Rain" → Word: "Calm" 8), Player 1: "Apple" | Player 2: "Tree" → Word: "Orchard" 88, Player 1: "Ocean" | Player 2: "Wave" → Word: "Surf" 8, Player 1: "Butter" | Player 2: "Bread" → Word: "Toast" 8, Player 1: "Phone" | Player 2: "Call" → Word: "Conversation" 8, Player 1: "Fire" | Player 2: "Heat" → Word: "Warmth" 39', NULL, NULL, NULL),
  ('funflow', 'serotonin', 12, 'Imitation Game', NULL, 'Mimic someone you both know, and your partner guesses who it is.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('funflow', 'dopamine', 'Dopamine', NULL, 3);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('funflow', 'dopamine', 0, '20 Questions', NULL, 'Think of something, and your partner has 20 yes-or-no questions to guess what it is', '["Is it alive?", "Can it be found in a house?", "Is it larger than a car?", "Is it used daily?", "Is it something you can hold?", "Does it have wheels?", "Is it something you wear?", "Is it related to technology?", "Does it make noise?", "Can it be eaten?"]', NULL, NULL),
  ('funflow', 'dopamine', 1, 'Riddle Me This', NULL, '', '["What has keys but can’t open locks? Answer: A piano", "What gets wetter as it dries? Answer: A towel", "I speak without a mouth and hear without ears. I have no body, but I come alive with wind. What am I? Answer: An echo", "What has to be broken before you can use it? Answer: An egg", "What has a heart that doesn’t beat? Answer: An artichoke", "What has a head, a tail, but no body? Answer: A coin", "What belongs to you but others use it more? Answer: Your name", "The more you take, the more you leave behind. What am I? Answer: Footsteps", "What comes once in a minute, twice in a moment, but never in a thousand years? Answer: The letter ''M''", "I’m tall when I’m young, and short when I’m old. What am I? Answer: A candle", "What has hands but cannot clap? Answer: A clock", "I go up but never come down. What am I? Answer: Your age", "What runs but never walks, has a bed but never sleeps? Answer: A river", "What is so fragile that saying its name breaks it? Answer: Silence"]', NULL, NULL),
  ('funflow', 'dopamine', 2, 'Guess the Number', NULL, 'Think of a number between 1 and 100, and your partner guesses it. Give hints like "higher" or "lower."', NULL, NULL, NULL),
  ('funflow', 'dopamine', 3, 'Rock, Paper, Scissors', NULL, 'Simultaneously throw rock, paper, or scissors. Rock beats scissors, scissors beat paper, & paper beats rock.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 4, 'Alphabet Game', NULL, 'Name items in a chosen category that start with each letter of the alphabet in turn. Sample Categories% .h Animals: Alligator, Bear, Cat, etch "h Cities: Amsterdam, Berlin, Chicago, etch h Fruits: Apple, Banana, Cherry, etch h Jobs: Accountant, Banker, Chef, etch h Famous Brands: Adidas, BMW, Coca-Cola, etch Ch Movies: Avatar, Batman, Casablanca, etch 5h Countries: Argentina, Brazil, Canada, etch h Celebrities: Angelina Jolie, Brad Pitt, Cameron Diaz, etch \h Foods: Avocado, Burger, Carrot, etch .h TV Shows: American Idol, Breaking Bad, Community, etc.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 5, 'Category Countdown', NULL, 'Name items in a chosen category. The game continues until someone can’t think of an item.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 6, 'Reverse Alphabet', NULL, 'Take turns saying the alphabet backward. If someone messes up, they start over.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 7, 'Tongue Twisters', NULL, 'MA She sells seashells by the seashoreA BA Red lorry, yellow lorry, blue lorry, black lorryA 6A Peter Piper picked a peck of pickled peppersA (A Six slippery snails slid slowly seawardA %A I saw Susie sitting in a shoeshine shopA 5A Can you can a can as a canner can can a can* "A Kaccha papad, pakka papadA 0A A proper copper coffee potA A Thin sticks, thick bricks, this kicksA M A Blue Bulb Black Bull Blue Bull Black BulbA MMA I saw a kitten eating chicken in the kitchenA MBA Black bug bleeds black bloodA M6A He threw three free throwsA M(A A snake sneaks to seek a snackA M%A The big black bug bit the big black bearA M5A Eleven benevolent elephantsA M"A Four furious friends fought for the phoneA M0A Truly rural. Really leery, rarely LarryA M A Sheena leads, Sheila needs. Rory’s lawnA B A We surely shall see the sunshine soonA BMA Unique New York, unique New YorkA BBA Three thin thieves thought a 1000 thoughtsA B6A Four furious frogs fretted over fliesA B(A A noisy noise annoys an oysterA B%A Fred fed Ted bread, and Ted fed Fred bread.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 8, 'Rhyme Time', NULL, 'Take turns saying words that rhyme until someone can’t come up with a new one.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 9, 'Word Ladders', NULL, 'Change one letter of a word to form a new word. Continue until someone can’t think of a new one.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 10, 'Synonym Challenge', NULL, 'Say a word, and your partner must respond with a synonym. The game continues until someone can’t think of a new word.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 11, 'Find the Pattern', NULL, 'Think of a pattern or sequence, and your partner guesses what comes next.', NULL, NULL, NULL),
  ('funflow', 'dopamine', 12, 'Counting Game', NULL, 'Count aloud, replacing certain numbers with a word or action. Continue until someone makes a mistake', NULL, NULL, NULL);
INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('relationship_method', 'Pick a relationship and draw a card. Do the challenge today, then draw again tomorrow.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'servitude', 'Serve & Lead', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'servitude', 0, 'Daily Efficiency Booster Challenge', NULL, 'Have two focus sessions of 2 hours each, using the Pomodoro technique (25 minutes of work followed by a 5-minute break) or one 90-minute session with a single 5-minute break.', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 1, 'Skill Development Daily Challenge', NULL, 'Spend 20 minutes each day learning or improving a professional or community-related skill.', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 2, 'Daily Public Speaking Practice', NULL, 'Practice speaking or presenting for 10 minutes a day (e.g., rehearse a speech, speak in front of a mirror, or record yourself).', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 3, 'Daily Networking & Service Challenge', NULL, 'Initiate a conversation with a stranger or connect with an existing friend daily, and perform a small act of service.', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 4, 'Daily Leadership Action Challenge', NULL, 'Take one action that demonstrates leadership, whether in a professional context or community service (e.g., organizing tasks, leading a discussion).', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 5, 'Daily Professional & Spiritual Contribution', NULL, 'Contribute 15 minutes daily to writing, sharing knowledge, or engaging in spiritual service.', NULL, NULL, NULL),
  ('relationship_method', 'servitude', 6, 'Daily Accountability Check-Ins', NULL, 'Spend 10 minutes daily reflecting and updating your accountability group or journal on your progress.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'friendships', 'Friendships', NULL, 1);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'friendships', 0, 'Daily Exploration Challenge', NULL, 'Initiate a conversation with a stranger each day.', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 1, 'Daily Connection with Friends', NULL, 'Reach out to an existing friend or maintain contact daily through a meaningful conversation.', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 2, 'Daily Hobby and Passion Practice', NULL, 'Spend 20 minutes daily on a hobby and share your progress with a friend.', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 3, 'Daily Gratitude Practice', NULL, 'Express gratitude to a friend or for your friendships by writing or verbally acknowledge them every day.', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 4, 'Daily Adventure Planning', NULL, 'Spend 10 minutes daily planning a small adventure or activity with friends, even if it’s just for the future.', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 5, 'Daily Conflict Resolution & Reflection', NULL, 'Reflect daily on any conflicts and take steps to address them (e.g., reach out for reconciliation or plan how to approach the situation).', NULL, NULL, NULL),
  ('relationship_method', 'friendships', 6, 'Daily Support Action', NULL, 'Offer a supportive gesture or words of encouragement to a friend each day.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'caretakers', 'Family', NULL, 2);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'caretakers', 0, 'Daily Inner Child Healing & Forgiveness', NULL, 'Spend 10 minutes daily on shadow work or journaling focused on healing your inner child and practicing forgiveness.', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 1, 'Daily Connection with Parents', NULL, 'Engage in a meaningful conversation or share a moment with your parents for 10 minutes each day.', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 2, 'Daily Family Tradition Practice', NULL, 'Contribute to or participate in a family tradition for at least 10 minutes each day.', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 3, 'Daily Listening Practice', NULL, 'Practice active listening with a family member for 10 minutes each day, focusing entirely on their words and emotions.', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 4, 'Daily Generational Learning', NULL, 'Spend 10 minutes daily learning something from your parents or elders (e.g., a skill, recipe, or story).', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 5, 'Daily Spiritual Connection w/Family', NULL, 'Engage in a spiritual practice with your family for 10 minutes daily (e.g., prayer, meditation, or chanting).', NULL, NULL, NULL),
  ('relationship_method', 'caretakers', 6, 'Daily Family Interaction', NULL, 'Spend 15 minutes daily in a family activity that strengthens bonds, such as a shared meal, storytelling, or a group walk.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'lover', 'Couples', NULL, 3);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'lover', 0, 'Communication Daily Practice', NULL, 'Dedicate 10 minutes daily to practicing active listening and clear communication with your partner.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 1, 'Daily Quality Time', NULL, 'Spend at least 20 minutes daily on a shared activity or meaningful interaction with your partner.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 2, 'Daily Gratitude and Appreciation', NULL, 'Express gratitude or appreciation to your partner daily, either verbally, through a note, or a small gesture.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 3, 'Daily New Experience', NULL, 'Try something new together with your partner daily, even if it’s a small change in routine or a new conversation topic.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 4, 'Daily Conflict Resolution', NULL, 'Reflect on any disagreements & take steps toward resolving them daily, ensuring clear communication & empathy.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 5, 'Daily Future Planning Talk', NULL, 'Spend 10 minutes daily discussing future plans or goals with your partner, even if just small steps.', NULL, NULL, NULL),
  ('relationship_method', 'lover', 6, 'Daily Intimacy and Vulnerability Practice', NULL, 'Daily Intimacy and Vulnerability Practice', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'self', 'Self', NULL, 4);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'self', 0, 'Daily Self Care Routine', NULL, 'Dedicate at least 20 minutes daily to a self-care activity (e.g., skincare, relaxation, or a bath).', NULL, NULL, NULL),
  ('relationship_method', 'self', 1, 'Daily Mindfulness and Meditation', NULL, 'Practice mindfulness, breathwork, or meditation for 10 minutes each day.', NULL, NULL, NULL),
  ('relationship_method', 'self', 2, 'Daily Healthy Living', NULL, 'Focus on one aspect of healthy living daily, such as hydration (drink 2 liters of water), healthy eating (3 servings of fruits/ vegetables), or incorporating Ayurvedic or herbal practices and nootropics.', NULL, NULL, NULL),
  ('relationship_method', 'self', 3, 'Daily Reflection and Shadow Work', NULL, 'Spend 10 minutes each day reflecting on your thoughts, emotions, and progress in a journal, incorporating shadow work as needed.', NULL, NULL, NULL),
  ('relationship_method', 'self', 4, 'Daily Running and Physical Wellness', NULL, 'Engage in running or another form of exercise for at least 20 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'self', 5, 'Daily Creative Expression', NULL, 'Spend 15 minutes daily on a creative activity like drawing, writing, or crafting.', NULL, NULL, NULL),
  ('relationship_method', 'self', 6, 'Daily Book Reading', NULL, 'Dedicate 20 minutes daily to reading a book, listening to an audiobook, or watching an educational video.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'guru', 'Guru', NULL, 5);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'guru', 0, 'Daily Sadhana', NULL, 'Spend 20 minutes daily on spiritual practices such as chanting, meditation, or prayer.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 1, 'Daily Spiritual Study', NULL, 'Read or study spiritual texts or teachings for 15 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 2, 'Daily Service and Seva', NULL, 'Engage in an act of service inspired by your Guru for 10 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 3, 'Daily Reflection on Teachings', NULL, 'Reflect on your spiritual journey and insights from your Guru for 10 minutes each day.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 4, 'Daily Teaching and Sharing', NULL, 'spiritual teachings or wisdom with at least one person daily.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 5, 'Daily Community Engagement', NULL, 'Participate in a spiritual community event, discussion, or practice for at least 10 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'guru', 6, 'Daily Guru Reflection', NULL, 'Write or meditate on the impact of your Guru on your life for 10 minutes daily, or share a teaching with others.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('relationship_method', 'divine', 'Divine', NULL, 6);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('relationship_method', 'divine', 0, 'Daily Chanting and Prayer', NULL, 'Engage in chanting or prayer for 10 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 1, 'Daily Divine Connection', NULL, 'Spend 10 minutes daily in nature or a spiritual space to connect with the divine.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 2, 'Daily Gratitude to the Divine', NULL, 'Express gratitude for divine blessings for 5 minutes daily, either in writing or meditation.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 3, 'Daily Ritual Practice', NULL, 'Perform a personal spiritual ritual or practice for 10 minutes daily.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 4, 'Daily Spiritual Book Reading', NULL, 'Dedicate 15 minutes daily to reading a spiritual book or sacred text.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 5, 'Daily Meditation on the Divine', NULL, 'Meditate for 10 minutes daily, focusing on your connection with the divine.', NULL, NULL, NULL),
  ('relationship_method', 'divine', 6, 'Daily Legacy of Faith Reflection', NULL, 'Write or contemplate your spiritual beliefs & experiences for 10 mins daily.', NULL, NULL, NULL);
INSERT INTO card_games (game_key, how_to, special_json, special_note, rules_json) VALUES ('roast_or_flirt', 'Draw a card. Read the roast out loud, or flip it and pick a flirt. Keep it playful and never mean.', NULL, NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('roast_or_flirt', 'english', 'English', NULL, 0);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('roast_or_flirt', 'english', 0, NULL, 'Roast', 'You light up a room, but only when you leave it.', NULL, 'Flirt', 'Do you have a name, or can I call you mine?'),
  ('roast_or_flirt', 'english', 1, NULL, 'Roast', 'You’re not entirely useless, because you can surely be used as a bad example.', NULL, 'Flirt', 'Are you French? Because Eiffel for you.'),
  ('roast_or_flirt', 'english', 2, NULL, 'Roast', 'Your presence makes me long for your absence.', NULL, 'Flirt', 'Are you Australian? Because when I look at you, I feel down under.'),
  ('roast_or_flirt', 'english', 3, NULL, 'Roast', 'I never forget a face—but in your case, I’ll make an exception.', NULL, 'Flirt', 'You must be made of copper and tellurium because you’re Cu-Te.'),
  ('roast_or_flirt', 'english', 4, NULL, 'Roast', 'I’d agree with you, but then we’d both be wrong.', NULL, 'Flirt', 'Are you a magician? Because whenever I look at you, everyone else disappears.'),
  ('roast_or_flirt', 'english', 5, NULL, 'Roast', 'I’d explain it to you, but I left my crayons at home.', NULL, 'Flirt', 'Are you a camera? Because I can’t stop smiling every time I look at you.'),
  ('roast_or_flirt', 'english', 6, NULL, 'Roast', 'I’m not insulting you; I’m describing you.', NULL, 'Flirt', 'Do you have a map? I keep getting lost in your eyes.'),
  ('roast_or_flirt', 'english', 7, NULL, 'Roast', 'I’m jealous of people who haven’t met you.', NULL, 'Flirt', 'Is your name Wi-Fi? Because I’m feeling a connection.'),
  ('roast_or_flirt', 'english', 8, NULL, 'Roast', 'I thought of you today. It reminded me to take out the trash.', NULL, 'Flirt', 'If you were a vegetable, you’d be a cute-cumber.'),
  ('roast_or_flirt', 'english', 9, NULL, 'Roast', 'You must have been born on a highway because that''s where most accidents happen.', NULL, 'Flirt', 'You must be tired because you’ve been running through my mind all day.'),
  ('roast_or_flirt', 'english', 10, NULL, 'Roast', 'You’re like a software update. Whenever I see you, I think, ‘Not now.’', NULL, 'Flirt', 'Can I follow you home? Cause my GPS just told me I’m lost in your eyes.'),
  ('roast_or_flirt', 'english', 11, NULL, 'Roast', 'If laughter is the best medicine, your face must be curing the world.', NULL, 'Flirt', 'Is your dad a boxer? Because you’re a knockout!'),
  ('roast_or_flirt', 'english', 12, NULL, 'Roast', 'I’d give you a nasty look, but you already have one.', NULL, 'Flirt', 'Are you a parking ticket? Because you’ve got “fine” written all over you.'),
  ('roast_or_flirt', 'english', 13, NULL, 'Roast', 'You look like something I’d draw with my left hand.', NULL, 'Flirt', 'If you were a fruit, you’d be a fineapple.'),
  ('roast_or_flirt', 'english', 14, NULL, 'Roast', 'You are proof that even God makes mistakes.', NULL, 'Flirt', 'Are you from Tennessee? Because you’re the only ten I see.'),
  ('roast_or_flirt', 'english', 15, NULL, 'Roast', 'You’d be really attractive if you weren’t trying so hard.', NULL, 'Flirt', 'Can you lend me a pencil? I want to erase your past and write our future.'),
  ('roast_or_flirt', 'english', 16, NULL, 'Roast', 'It’s impressive how you always manage to stand out, even when you’re wrong.', NULL, 'Flirt', 'Is your name Google? Because you’ve got everything I’m searching for.'),
  ('roast_or_flirt', 'english', 17, NULL, 'Roast', 'Your confidence is amazing, especially considering your situation.', NULL, 'Flirt', 'Are you a magician? Because whenever I look at you, everything else disappears.'),
  ('roast_or_flirt', 'english', 18, NULL, 'Roast', 'You’re so brave to wear that in public.', NULL, 'Flirt', 'Can I take a picture of you to prove to my friends that angels exist?'),
  ('roast_or_flirt', 'english', 19, NULL, 'Roast', 'You have a great sense of humor —it’s just not for everyone.', NULL, 'Flirt', 'Are you Netflix? Because I could binge-watch you all day.'),
  ('roast_or_flirt', 'english', 20, NULL, 'Roast', 'I admire how you’ve made that look work for you—it’s not easy.', NULL, 'Flirt', 'If you were a cat, you’d purr-fect.'),
  ('roast_or_flirt', 'english', 21, NULL, 'Roast', 'You’re cute... for someone who’s not my type.', NULL, 'Flirt', 'Are you a star? Because your beauty lights up the night.'),
  ('roast_or_flirt', 'english', 22, NULL, 'Roast', 'You’re almost as smooth as you think you are.', NULL, 'Flirt', 'Do you have a Band-Aid? Because I just scraped my knee falling for you.'),
  ('roast_or_flirt', 'english', 23, NULL, 'Roast', 'You’ve got potential—once you figure out what you’re doing.', NULL, 'Flirt', 'Are you a beaver? Because damn.'),
  ('roast_or_flirt', 'english', 24, NULL, 'Roast', 'You’re cute... when you’re not talking.', NULL, 'Flirt', 'Do you believe in love at first sight, or should I walk by again?');
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('roast_or_flirt', 'english', 25, NULL, 'Roast', 'You’re like my favorite snack— great in small doses.', NULL, 'Flirt', 'You’re like a broken pencil... pointless to resist.'),
  ('roast_or_flirt', 'english', 26, NULL, 'Roast', 'That was cute—just like your fragile ego.', NULL, 'Flirt', 'Is your name Chapstick? Because you’re da balm.'),
  ('roast_or_flirt', 'english', 27, NULL, 'Roast', 'Wow, you really thought that was going to work, didn’t you?', NULL, 'Flirt', 'Can I borrow a kiss? I promise I’ll give it back.'),
  ('roast_or_flirt', 'english', 28, NULL, 'Roast', 'If I had a dollar for every good idea you had, I’d still be broke.', NULL, 'Flirt', 'Do you have a mirror in your pocket? Because I see myself in your pants.'),
  ('roast_or_flirt', 'english', 29, NULL, 'Roast', 'Let’s pretend that made sense... just for your sake.', NULL, 'Flirt', 'Are you Cinderella? Because you’re making me forget about all my other shoes.'),
  ('roast_or_flirt', 'english', 30, NULL, 'Roast', 'You’ve got the persistence of someone who should’ve quit by now.', NULL, 'Flirt', 'Are you a snowstorm? Because you’ve just made my heart freeze.'),
  ('roast_or_flirt', 'english', 31, NULL, 'Roast', 'It’s okay to give up now—no one’s judging.', NULL, 'Flirt', 'You must be a magician because every time I look at you, everyone else disappears.'),
  ('roast_or_flirt', 'english', 32, NULL, 'Roast', 'I appreciate the effort—now, how about some results?', NULL, 'Flirt', 'Is your smile a spell? Because I’m enchanted by you.'),
  ('roast_or_flirt', 'english', 33, NULL, 'Roast', 'It’s cute how you think overthinking is a superpower.', NULL, 'Flirt', 'Do you like raisins? How about a date?'),
  ('roast_or_flirt', 'english', 34, NULL, 'Roast', 'You’d be unstoppable if you could just stay on topic.', NULL, 'Flirt', 'You’re like a dictionary... you add meaning to my life.'),
  ('roast_or_flirt', 'english', 35, NULL, 'Roast', 'You’d be a great leader—if anyone could follow your train of thought.', NULL, 'Flirt', 'Are you a bank loan? Because you have my interest.'),
  ('roast_or_flirt', 'english', 36, NULL, 'Roast', 'I admire how you always find a way to be right, even when you’re wrong.', NULL, 'Flirt', 'Can I follow you home? Cause I can’t seem to stop following my dreams.'),
  ('roast_or_flirt', 'english', 37, NULL, 'Roast', 'You’re proof that practice doesn’t always make perfect.', NULL, 'Flirt', 'Are you an angel? Because heaven is missing one.'),
  ('roast_or_flirt', 'english', 38, NULL, 'Roast', 'You’ve got an answer for everything—except the questions that matter.', NULL, 'Flirt', 'If I could rearrange the alphabet, I’d put U and I together.'),
  ('roast_or_flirt', 'english', 39, NULL, 'Roast', 'You’re like a superhero—minus the superpowers.', NULL, 'Flirt', 'You must be a parking ticket because you’ve got fine written all over you.'),
  ('roast_or_flirt', 'english', 40, NULL, 'Roast', 'You’re really good at seeing the bright side—too bad it’s blinding you.', NULL, 'Flirt', 'Do you have a pencil? Because I want to draw a future with you.'),
  ('roast_or_flirt', 'english', 41, NULL, 'Roast', 'You’ve got a way with people— mostly with driving them crazy.', NULL, 'Flirt', 'You must be made of stardust because you’re out of this world.'),
  ('roast_or_flirt', 'english', 42, NULL, 'Roast', 'If common sense was an app, you’d still forget to download it.', NULL, 'Flirt', 'Are you a sunrise? Because you brighten up my day.'),
  ('roast_or_flirt', 'english', 43, NULL, 'Roast', 'Your energy’s giving ‘last minute homework vibes.’', NULL, 'Flirt', 'Is your middle name Gillette? Because you’re the best a man can get.'),
  ('roast_or_flirt', 'english', 44, NULL, 'Roast', 'That smile’s doing all the heavy lifting, isn’t it?', NULL, 'Flirt', 'Can I follow you? Cause my mom told me to follow my dreams.'),
  ('roast_or_flirt', 'english', 45, NULL, 'Roast', 'You’re the life of the party... when you’re not there.', NULL, 'Flirt', 'Are you a campfire? Because you’re hot and I want s’more.'),
  ('roast_or_flirt', 'english', 46, NULL, 'Roast', 'That was a solid 6/10—would love to see you aim higher.', NULL, 'Flirt', 'Are you a camera? Because you’ve captured my heart.'),
  ('roast_or_flirt', 'english', 47, NULL, 'Roast', 'Is that your best shot, or are you saving the good stuff?', NULL, 'Flirt', 'If looks could kill, you’d definitely be a weapon of mass destruction.'),
  ('roast_or_flirt', 'english', 48, NULL, 'Roast', 'You’d be dangerous if you had better comebacks.', NULL, 'Flirt', 'Are you an Instagram post? Because I’m double-tapping that.'),
  ('roast_or_flirt', 'english', 49, NULL, 'Roast', 'You must be tired—carrying all that attitude around.', NULL, 'Flirt', 'You must be a broom because you’ve swept me off my feet.');
