INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('roast_or_flirt', 'hinglish', 0, NULL, 'Roast', 'Tum room ko bright kar dete ho, lekin sirf jab tum usse chhodte ho.', NULL, 'Flirt', 'Tumne smile ka patent karwaya hai kya? Kyunki tumhari smile toh duniya ki sabse unique lagti hai.'),
  ('roast_or_flirt', 'hinglish', 1, NULL, 'Roast', 'Tumhari baatein to waise hi bekaar hain jaise baarish mein chhata na hona.', NULL, 'Flirt', 'Tumhari smile ne mere heart ka password hack kar liya hai.'),
  ('roast_or_flirt', 'hinglish', 2, NULL, 'Roast', 'Tum puri tarah se bekaar nahi ho, kyunki tumhe ek bad example ke roop mein zaroor use kiya ja sakta hai.', NULL, 'Flirt', 'Tum mere glasses ho kya? Kyunki tumhare bina meri duniya bilkul blurry hai.'),
  ('roast_or_flirt', 'hinglish', 3, NULL, 'Roast', 'Tumhare jokes sunke hansi aa jaati hai, bas kabhi-kabhi sochta hoon, kyu?', NULL, 'Flirt', 'Jab tum hans rahi thi, lagta tha background mein koi romantic gaana baj raha hai.'),
  ('roast_or_flirt', 'hinglish', 4, NULL, 'Roast', 'Tumhari maujoodgi mujhe tumhari non-maujoodgi ke liye tarasne pe majboor karti hai.', NULL, 'Flirt', 'Tum, me, aur ek cup coffee— sounds like the perfect plan!'),
  ('roast_or_flirt', 'hinglish', 5, NULL, 'Roast', 'Tumhara sense of humor utna hi rare hai jitna unicorn.', NULL, 'Flirt', 'Tumhara naam kya hai? Kyunki bas ‘Perfect’ se kaam nahi chalega.'),
  ('roast_or_flirt', 'hinglish', 6, NULL, 'Roast', 'Main kabhi chehre nahi bhoolta —par tumhare case mein exception banaunga.', NULL, 'Flirt', 'Lagta hai aaj meri lucky day hai, kyunki tumhe dekh liya.'),
  ('roast_or_flirt', 'hinglish', 7, NULL, 'Roast', 'Kabhi-kabhi sochta hoon ki tumhare jokes ko log sirf kyun sehte hain?', NULL, 'Flirt', 'Kya tum Black Friday sale ho? Kyunki tumhe miss karna afford nahi kar sakta.'),
  ('roast_or_flirt', 'hinglish', 8, NULL, 'Roast', 'Main tumhare saath sehmat hota, lekin fir hum dono galat hote.', NULL, 'Flirt', 'Tum party ka main event ho, sab tumhe dekhne aaye hain.'),
  ('roast_or_flirt', 'hinglish', 9, NULL, 'Roast', 'Tumhare efforts waise hi kaam aate hain jaise bina petrol ki car.', NULL, 'Flirt', 'Tum sabka attention grab karne ka license le kar aayi ho kya?'),
  ('roast_or_flirt', 'hinglish', 10, NULL, 'Roast', 'Main tumhe samjhata, lekin apne crayons ghar par chhod aaya hoon.', NULL, 'Flirt', 'Pata hai tumhare bina kaise lagta hai? Jaise maggie bina masale ke.'),
  ('roast_or_flirt', 'hinglish', 11, NULL, 'Roast', 'Tumse baat karna waise hi hai jaise bina internet ke Google karna.', NULL, 'Flirt', 'Yeh tumhare paas GPS hai kya? Kyunki tumse milke mera direction hi change ho gaya.'),
  ('roast_or_flirt', 'hinglish', 12, NULL, 'Roast', 'Main tumhe insult nahi kar raha; main tumhe describe kar raha hoon.', NULL, 'Flirt', 'Mujhe bas ek baat bata do, tumhe dekhne ka charge kitna hai?'),
  ('roast_or_flirt', 'hinglish', 13, NULL, 'Roast', 'Tumse behas karna aisa hai jaise baarish mein umbrella ke bina chalna—unavoidable lekin uncomfortable.', NULL, 'Flirt', 'Tumhare saath ek selfie lena hai, taaki logon ko dikhau ki dreams sach hote hain.'),
  ('roast_or_flirt', 'hinglish', 14, NULL, 'Roast', 'Main un logon se jalan karta hoon jinhone tumse kabhi nahi mila.', NULL, 'Flirt', 'Tum alarm clock ho kya? Kyunki tumhe dekhte hi main full jag gaya hoon.'),
  ('roast_or_flirt', 'hinglish', 15, NULL, 'Roast', 'Tumse baat karke lagta hai ki mute button ka invention genius tha.', NULL, 'Flirt', 'Tumhare aas paas koi volume control button hai kya? Kyunki tumhe dekh ke dil ki dhadkan loud ho gayi.'),
  ('roast_or_flirt', 'hinglish', 16, NULL, 'Roast', 'Aaj tumhari yaad aayi. Isne mujhe kachra nikalne ki yaad dila di.', NULL, 'Flirt', 'Tum koi science experiment ho? Kyunki tumhe dekh ke chemistry feel hoti hai.'),
  ('roast_or_flirt', 'hinglish', 17, NULL, 'Roast', 'Tumhara charm aur purani film ka hero, dono hi history mein kho chuke hain.', NULL, 'Flirt', 'Tum airport ho? Kyunki tumhare bina mere sapne land nahi kar paate.'),
  ('roast_or_flirt', 'hinglish', 18, NULL, 'Roast', 'Tum highway par paida hue hoge, kyunki wahi zyada accidents hote hain.', NULL, 'Flirt', 'Kya tum Bluetooth ho? Kyunki tumhare bina main connect nahi kar paa raha.'),
  ('roast_or_flirt', 'hinglish', 19, NULL, 'Roast', 'Tumhari baatein waise hi lambi hain jaise koi bina end ki kahani.', NULL, 'Flirt', 'Tum GIF ho kya? Kyunki tumhe baar-baar dekhne ka mann karta hai.'),
  ('roast_or_flirt', 'hinglish', 20, NULL, 'Roast', 'Tum software update ki tarah ho. Jab bhi tumhe dekhta hoon, sochta hoon, ‘Not now.’', NULL, 'Flirt', 'Tumhari aankhon ka ‘Do Not Disturb’ sign kab hataogi?'),
  ('roast_or_flirt', 'hinglish', 21, NULL, 'Roast', 'Tumhare mood swings waise hi jaldi badalte hain jaise naye social media trends.', NULL, 'Flirt', 'Tumhare saath zindagi full HD feel ho rahi hai.'),
