  ('shadowflow', 'reflections', 4, NULL, NULL, 'How can I give more love and attention to the parts of me that I’ve judged?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 5, NULL, NULL, 'What is one truth I am afraid to admit to myself?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 6, NULL, NULL, 'What past experience am I ready to release and forgive?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 7, NULL, NULL, 'How do I sabotage my own growth, and why?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 8, NULL, NULL, 'Where do I still seek external validation, and how can I better validate myself?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 9, NULL, NULL, 'What lesson is my shadow trying to teach me right now?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 10, NULL, NULL, 'How do I numb or distract myself from difficult emotions?', NULL, NULL, NULL),
