  ('shadowflow', 'reflections', 15, NULL, NULL, 'In what areas do I hold onto resentment or anger?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 16, NULL, NULL, 'What does success mean to me, and what fears do I associate with it?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 17, NULL, NULL, 'Where do I fear being vulnerable, and how can I open up?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 18, NULL, NULL, 'How can I turn my inner darkness into my greatest strength?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 19, NULL, NULL, 'What am I afraid of losing, and what does that fear teach me?', NULL, NULL, NULL),
  ('shadowflow', 'reflections', 20, NULL, NULL, 'Where am I seeking control, and how can I let go?', NULL, NULL, NULL),
