INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('workflow', 'truth', 'Truth or Truth', NULL, 5);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('workflow', 'truth', 0, NULL, NULL, '', '["Have you ever badmouthed a boss behind their back?", "Have you ever ignored a colleague’s request for help because you were too busy?"]', NULL, NULL),
  ('workflow', 'truth', 1, NULL, NULL, '', '["Have you ever lied about your productivity at work?", "Have you ever felt guilty about taking a personal day?"]', NULL, NULL),
  ('workflow', 'truth', 2, NULL, NULL, '', '["Have you ever thrown a coworker under the bus to save yourself?", "Have you ever pretended to be busy to avoid a task?"]', NULL, NULL),
  ('workflow', 'truth', 3, NULL, NULL, '', '["Have you ever secretly enjoyed office gossip?", "Have you ever avoided a difficult conversation with a colleague?"]', NULL, NULL),
  ('workflow', 'truth', 4, NULL, NULL, '', '["Have you ever exaggerated your role in a project?", "Have you ever taken credit for an idea that wasn’t yours?"]', NULL, NULL),
  ('workflow', 'truth', 5, NULL, NULL, '', '["Have you ever snooped through a colleague’s desk?", "Have you ever ignored a deadline because you knew you wouldn’t get caught?"]', NULL, NULL),
  ('workflow', 'truth', 6, NULL, NULL, '', '["Have you ever shared confidential information with the wrong person?", "Have you ever ghosted a colleague’s email request?"]', NULL, NULL),
  ('workflow', 'truth', 7, NULL, NULL, '', '["Have you ever lied about how much time you spent on a project?", "Have you ever lied to avoid a meeting?"]', NULL, NULL),
  ('workflow', 'truth', 8, NULL, NULL, '', '["Have you ever avoided a difficult client by faking being busy?", "Have you ever secretly laughed at a coworker’s mistake?"]', NULL, NULL),
  ('workflow', 'truth', 9, NULL, NULL, '', '["Have you ever made a work decision you regretted immediately?", "Have you ever covered up a mistake you made at work?"]', NULL, NULL);
INSERT INTO card_decks (game_key, deck_key, name, hint, position) VALUES ('workflow', 'twotruths', 'Two Truths and a Lie', NULL, 6);
INSERT INTO cards (game_key, deck_key, position, title, label, text, list_json, alt_label, alt_text) VALUES
  ('workflow', 'twotruths', 0, NULL, NULL, '', '["Have you ever faked being sick to avoid a work event you didn’t want to attend?", "Have you ever deleted a Slack message or email after realizing it was inappropriate?", "Have you ever stolen someone else’s lunch from the fridge?"]', NULL, NULL),
  ('workflow', 'twotruths', 1, NULL, NULL, '', '["Have you ever secretly hoped a project would fail just so you wouldn’t have to work on it anymore?", "Have you ever made up a client’s feedback to justify changing something you didn’t like?", "Have you ever used a company credit card for something personal?"]', NULL, NULL),
  ('workflow', 'twotruths', 2, NULL, NULL, '', '["Have you ever snooped through a coworker’s files or notes when they weren’t looking?", "Have you ever exaggerated your workload to get out of more assignments?", "Have you ever pretended to agree with a bad idea in a meeting to avoid confrontation?"]', NULL, NULL),
  ('workflow', 'twotruths', 3, NULL, NULL, '', '["Have you ever accidentally overheard a confidential conversation and used the information later?", "Have you ever ignored a client or coworker’s emails for days just because you didn’t feel like replying?", "Have you ever used a personal connection to get ahead in your career?"]', NULL, NULL),
  ('workflow', 'twotruths', 4, NULL, NULL, '', '["Have you ever taken credit for a colleague’s work when they weren’t around to defend it?", "Have you ever intentionally missed a deadline because you knew no one would notice?", "Have you ever pretended to be busy while secretly binge-watching a series during work hours?"]', NULL, NULL),
  ('workflow', 'twotruths', 5, NULL, NULL, '', '["Have you ever used your company’s software for personal projects without permission?", "Have you ever thrown a colleague under the bus to cover up your own mistake?", "Have you ever lied about completing a task, hoping no one would check?"]', NULL, NULL),
  ('workflow', 'twotruths', 6, NULL, NULL, '', '["Have you ever intentionally kept important information from your coworkers just to gain an advantage?", "Have you ever pretended to agree with your boss’s terrible idea just to avoid a long discussion?", "Have you ever given bad advice to a coworker on purpose because you were jealous?"]', NULL, NULL),
  ('workflow', 'twotruths', 7, NULL, NULL, '', '["Have you ever faked technical difficulties to avoid a meeting or presentation?", "Have you ever shared confidential company information with someone outside the organization?", "Have you ever told a client you were unavailable because you just didn’t want to deal with them?"]', NULL, NULL),
  ('workflow', 'twotruths', 8, NULL, NULL, '', '["Have you ever used work hours to secretly apply for another job?", "Have you ever sabotaged a coworker’s work to make yourself look better?", "Have you ever let someone else take the blame for something you did?"]', NULL, NULL),
  ('workflow', 'twotruths', 9, NULL, NULL, '', '["Have you ever bad-mouthed a colleague to a manager to gain favor?", "Have you ever lied about how much progress you made on a project because you spent the time doing something else?", "Have you ever flirted with a coworker to get something you wanted?"]', NULL, NULL);
